// Search off the UI thread; fetch four compact volume indices at a time and cache them.
let generation=0;const cache=new Map(),pending=new Map();
async function load(volume){if(cache.has(volume))return cache.get(volume);if(!pending.has(volume))pending.set(volume,fetch('search'+volume+'.json?v=20261017-release1').then(r=>{if(!r.ok)throw Error('Search index unavailable');return r.json()}).then(rows=>{cache.set(volume,rows);return rows}).finally(()=>pending.delete(volume)));return pending.get(volume);}
self.onmessage=async event=>{const m=event.data;const run=++generation;if(m.type!=='search')return;let next=0,checked=0;const hits=[],failed=[];const send=complete=>{if(run!==generation)return;hits.sort((a,b)=>a._volume-b._volume||b.year-a.year);self.postMessage({id:m.id,hits,checked,complete,error:complete&&failed.length>0});};
await Promise.all(Array.from({length:4},async()=>{while(run===generation&&next<m.volumes.length){const volume=m.volumes[next++];try{const rows=await load(volume);if(run!==generation)return;for(const row of rows){const label=(row.year>0?'前':'')+Math.abs(row.year)+'年';if([label,row.reignLabel||'',row.king,row.text,...row.titles].join(' ').toLowerCase().includes(m.q)){const {text,...data}=row;hits.push({...data,_volume:volume,_indexKind:row.indexKind|| (volume===1?'editorial':'translationExcerpt'),_titleReview:row.titleReview});}}}catch(error){failed.push(volume);}checked++;if(checked%12===0)send(false);}}));send(true);
};
